function buildRollers(){
  const out = [];
  const base = (ser, D, s, B, extra) => {
    const S = SER[ser] || {};
    return Object.assign({ser, duty:S.duty, D, s, B, C:B+8, A:B+(S.addA||26), d:S.d, ch:S.ch, e:S.e, g:S.g, brg:S.brg, mat:S.mat}, extra||{});
  };
  const code = (r, des) => `${r.ser},${r.d}${(SER[r.ser]||{}).fl||'F'},${r.oe||r.D}${des},${r.C}`;
  const asaCode = r => `${asaSer(r.ser)}·${r.d}${(SER[r.ser]||{}).fl||'F'}·${r.oe||r.D}${asaDes(r.design)}·${r.C}`;
  /* رفت و برگشت ساده — دقیقاً مطابق جداول کاتالوگ */
  CATALOG_N.forEach(T => {
    const S = SER[T.ser] || {};
    T.rows.forEach(([B,A,bwF,bwV,bwT,wr,wt,loads]) => {
      const cap = T.sp.map((v,i) => loads[i]!=null ? `${v}→${loads[i]}` : null).filter(Boolean).join(' · ');
      const arrs = {flat:bwF, v2:bwV, t3:bwT};
      [['carry',['t3','v2','flat']],['ret',['flat','v2']]].forEach(([cat,list]) => list.forEach(arr => {
        const bw = arrs[arr]; if (!bw) return;
        const r = base(T.ser,T.D,T.s,B,{cat,design:T.des,bw,arr,d:T.d,d1:T.d1||T.d,ch:T.ch,brg:T.brg,e:T.e,g:T.g,wr,wt,cap});
        if (A) r.A = A;
        r.code = `${T.ser},${T.d}${S.fl||'F'},${T.D}${T.des},${r.C}`; out.push(r);
      }));
    });
  });
  /* ضربه‌گیر — دقیقاً مطابق جداول کاتالوگ (وزن هر سری از کاتالوگ) */
  CATALOG_NA.forEach(T => T.rows.forEach(([B,bwF,bwV,bwT,...wts]) => wts.forEach((wt,si) => {
    if (wt==null) return;
    const [ser,D,s] = T.base[si];
    [['flat',bwF],['v2',bwV],['t3',bwT]].forEach(([arr,bw]) => {
      if (!bw) return;
      const r = base(ser,D,s,B,{cat:'impact',design:'NA',bw,arr,oe:T.oe,ri:D,E:T.E,rt:'ET',wt});
      r.total = Math.floor(B/T.E);
      r.note = b('مطابق جدول کاتالوگ — تعداد رینگ = B ÷ E (محاسبه‌ای)','Per catalogue table — ring count = B ÷ E (calculated)');
      r.code = code(r,'NA'); out.push(r);
    });
  })));
  const ring = (list, des, cat, isNC) => list.forEach(g => g.b.forEach(([ser,D,s,mn,mx]) => g.r.forEach(row => {
    let bw,C,a,bb,c,t,side,central;
    if (isNC) [bw,C,a,bb,c,t,side,central] = row; else [bw,C,a,bb,t,side,central] = row;
    if (bw<mn || bw>mx) return;
    const r = base(ser,D,s,C-8,{cat,design:des,bw,arr:isNC?'v2':'flat',oe:g.oe,ri:D,E:g.E,a,b:bb,t,side,central});
    if (isNC) r.c = c;
    if (des==='NG'){ r.sideT='ER'; r.cenT='ER'; r.total=2*side+central; }
    else if (isNC){ r.E1=g.E1; r.sideT='ET'; r.cenT='ER'; r.total=side+central; }
    else { r.E1=g.E1; r.sideT='ET'; r.cenT='ER'; r.total=2*side+central; }
    if (g.note) r.note = g.note;
    r.code = code(r,des); out.push(r);
  })));
  ring(NG,'NG','retring',false); ring(NL,'NL','retring',false); ring(NC,'NC','retv',true);
  NM.forEach(g => g.b.forEach(([ser,D,s,mn,mx]) => g.r.forEach(([bw,C,L]) => {
    if (bw<mn || bw>mx) return;
    const r = base(ser,D,s,C-8,{cat:'helix',design:'NM',bw,arr:'flat',oe:g.oe,ri:D,E:38.5,L,
      note:b('رینگ مارپیچ با حلقه فولادی جوشی در دو سر نگه داشته می‌شود','Helix held by welded steel rings at both ends')});
    r.code = code(r,'NM'); out.push(r);
  })));
  /* فنر فولادی — S (PSV91/92/94) و NS (RTL1, M1, MPS1, MPR15) مطابق کاتالوگ */
  const CB = [[300,380],[400,500],[500,600],[650,750],[800,950],[1000,1150]];
  CAGE.forEach(([ser,D,des,w,oeNS]) => CB.forEach(([bw,B],i) => {
    const oe = oeNS || D;
    const r = base(ser,D,des==='NS'?(ser==='RTL1'?2:3):null,B,{cat:'cage',design:des,bw,arr:'flat',oe,wt:w[i],
      note:b('قفسه فنری فولادی متصل به دو درپوش — مطابق جدول کاتالوگ','Steel spring cage between two end caps — per catalogue table')});
    r.A = B + 26;
    r.code = `${ser},${r.d}${(SER[ser]||{}).fl||'F'},${D}${des},${r.C}`; out.push(r);
  }));
  GUIDE.forEach(([type,D,s,d,B,f,m,e,M,brg,wt]) => {
    const ser = type.startsWith('PS/') ? 'PSV1' : type.startsWith('MPS') ? 'MPS1' : type.startsWith('RTL') ? 'RTL1' : 'M1';
    out.push({cat:'guide',ser:type,duty:SER[ser].duty,design:'N',arr:'vert',D,s,d,B,f,m,e,M,brg,wt,
      code:`${type},${d},${D}N,${B}`,
      note:b('رولیک راهنمای عمودی لبه نوار — طول شافت طبق نقشه قاب','Vertical belt-edge guide roller — spindle length per frame drawing')});
  });
  const seen = {};
  out.forEach(r => { r.eqcode = r.code; r.code = r.cat==='guide' ? `${asaSer(r.ser)}·${r.d}·${r.D}N·${r.B}` : asaCode(r); });
  out.forEach(r => {
    let id = [r.cat,r.ser,r.D,r.oe||'',r.design,r.arr,r.bw||'',r.B,r.M||''].join('|');
    if (seen[id]) { seen[id]++; id += '#'+seen[id]; } else seen[id] = 1;
    r.id = id;
  });
  return out;
}

/* جدول سری‌ها برای تب «کلاس کاری» */
function buildSeries(){
  return Object.entries(SER).map(([k,S]) => ({id:k, ser:k, duty:S.duty, lv:S.lv, d:S.d, ch:S.ch, brg:S.brg, e:S.e, g:S.g, addA:S.addA, fl:S.fl, mat:S.mat,
    Ds:[...new Set(CATALOG_N.filter(T=>T.ser===k).map(T=>T.D))].sort((a,b)=>a-b).join(', ') || Object.keys(DIAS[k]||{}).join(', ')}));
}

